template <typename T, template <typename U> class Container>
class Adapter {
    // Container is the TTP
    Container<T> storage; // Instantiation is deferred
    T value;
};

// Example template usable as a TTP argument
template <typename V>
class ListType {
    V* ptr;
};

// Usage: Pass the template name, not an instance
Adapter<float, ListType> float_list_adapter;

// Compiler knows: ListType is a template
// Compiler defers: ListType<float> instantiation
// until Adapter<float, ListType> is used.
